def transform(grid):
    # Keep the two large filled rectangles; discard isolated/noisy pixels.
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    boxes = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            if len(cells) >= 4:
                boxes.append((min(y for y, x in cells), max(y for y, x in cells), min(x for y, x in cells), max(x for y, x in cells), color))
    out = [[bg] * w for _ in range(h)]
    for top, bottom, left, right, color in boxes:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = color
    return out

